<?php
namespace App\Http\Requests\Tenant;use App\Domain\AI\Runtime\Data\RuntimeQuestionData;use App\Domain\Network\Tenancy\TenantAccessService;use Illuminate\Foundation\Http\FormRequest;use Illuminate\Validation\Validator;
final class SimulateAgentRuntimeRequest extends FormRequest{public function authorize():bool{return app(TenantAccessService::class)->canManageTenant($this->user());}protected function prepareForValidation():void{$this->merge(['question'=>is_string($this->input('question'))?trim($this->input('question')):$this->input('question')]);}public function rules():array{return['question'=>['required','string','max:2000']];}public function withValidator(Validator$v):void{$v->after(function(Validator$v){foreach(array_keys($this->all())as$key)if(!in_array($key,['_token','question'],true))$v->errors()->add($key,'Este campo no está permitido.');if($v->errors()->isEmpty())try{$this->questionData();}catch(\InvalidArgumentException){$v->errors()->add('question','La pregunta no cumple el formato permitido.');}});}public function questionData():RuntimeQuestionData{return RuntimeQuestionData::from($this->validated('question'));}}
